CREATE TABLE carrier_freight_invoices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,carrier_service_id uuid NOT NULL,invoice_number text NOT NULL,invoice_date date NOT NULL,due_date date,currency text NOT NULL DEFAULT 'PHP',status text NOT NULL DEFAULT 'open' CHECK(status IN('open','in_review','approved','disputed','settled','void')),total_amount numeric(18,2) NOT NULL CHECK(total_amount>=0),source text NOT NULL DEFAULT 'manual' CHECK(source IN('manual','csv','api')),source_reference text,notes text,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),approved_at timestamptz,approved_by uuid REFERENCES users(id),settled_at timestamptz,UNIQUE(company_id,carrier_service_id,invoice_number),FOREIGN KEY(company_id,carrier_service_id) REFERENCES carrier_services(company_id,id));
CREATE TABLE carrier_freight_invoice_lines(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,invoice_id uuid NOT NULL REFERENCES carrier_freight_invoices(id) ON DELETE CASCADE,line_number integer NOT NULL,shipment_id uuid REFERENCES shipments(id),shipment_freight_cost_id uuid REFERENCES shipment_freight_costs(id),tracking_reference text,description text,billed_amount numeric(18,2) NOT NULL CHECK(billed_amount>=0),expected_amount numeric(18,2),variance_amount numeric(18,2) GENERATED ALWAYS AS(billed_amount-coalesce(expected_amount,0)) STORED,match_status text NOT NULL DEFAULT 'unmatched' CHECK(match_status IN('unmatched','matched','duplicate','missing_cost')),review_status text NOT NULL DEFAULT 'pending' CHECK(review_status IN('pending','approved','disputed','resolved')),review_note text,reviewed_at timestamptz,reviewed_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(invoice_id,line_number));
CREATE UNIQUE INDEX carrier_freight_invoice_lines_shipment_unique ON carrier_freight_invoice_lines(invoice_id,shipment_id) WHERE shipment_id IS NOT NULL;
CREATE TABLE carrier_freight_disputes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,invoice_line_id uuid NOT NULL UNIQUE REFERENCES carrier_freight_invoice_lines(id) ON DELETE CASCADE,status text NOT NULL DEFAULT 'open' CHECK(status IN('open','submitted','accepted','rejected','credited','closed')),reason_code text NOT NULL CHECK(reason_code IN('overcharge','duplicate','missing_shipment','wrong_service','wrong_weight','unauthorized_surcharge','other')),description text NOT NULL,owner_id uuid REFERENCES users(id),carrier_case_reference text,disputed_amount numeric(18,2) NOT NULL CHECK(disputed_amount>=0),credit_note_reference text,credit_amount numeric(18,2) CHECK(credit_amount>=0),opened_at timestamptz NOT NULL DEFAULT now(),opened_by uuid NOT NULL REFERENCES users(id),resolved_at timestamptz,resolved_by uuid REFERENCES users(id));
CREATE TABLE carrier_freight_dispute_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,dispute_id uuid NOT NULL REFERENCES carrier_freight_disputes(id) ON DELETE CASCADE,event_type text NOT NULL CHECK(event_type IN('opened','assigned','submitted','accepted','rejected','credited','closed','commented')),from_status text,to_status text,note text,reference text,amount numeric(18,2),created_at timestamptz NOT NULL DEFAULT now(),created_by uuid NOT NULL REFERENCES users(id));
ALTER TABLE carrier_freight_invoices ADD CONSTRAINT carrier_freight_invoices_company_id_unique UNIQUE(company_id,id);ALTER TABLE carrier_freight_invoice_lines ADD CONSTRAINT carrier_freight_invoice_lines_company_id_unique UNIQUE(company_id,id),ADD CONSTRAINT carrier_freight_invoice_lines_invoice_company_fk FOREIGN KEY(company_id,invoice_id) REFERENCES carrier_freight_invoices(company_id,id) ON DELETE CASCADE;ALTER TABLE carrier_freight_disputes ADD CONSTRAINT carrier_freight_disputes_company_id_unique UNIQUE(company_id,id),ADD CONSTRAINT carrier_freight_disputes_line_company_fk FOREIGN KEY(company_id,invoice_line_id) REFERENCES carrier_freight_invoice_lines(company_id,id) ON DELETE CASCADE;ALTER TABLE carrier_freight_dispute_events ADD CONSTRAINT carrier_freight_dispute_events_dispute_company_fk FOREIGN KEY(company_id,dispute_id) REFERENCES carrier_freight_disputes(company_id,id) ON DELETE CASCADE;
CREATE VIEW carrier_invoice_reconciliation_kpis WITH(security_invoker=true) AS SELECT i.company_id,o.warehouse_id,date_trunc('month',i.invoice_date)::date activity_month,i.currency,count(DISTINCT i.id) invoices,count(l.id) lines,count(l.id)FILTER(WHERE l.match_status='unmatched') unmatched_lines,count(l.id)FILTER(WHERE l.review_status='disputed') disputed_lines,sum(l.billed_amount) billed_amount,sum(coalesce(l.expected_amount,0)) expected_amount,sum(l.variance_amount) variance_amount,sum(coalesce(d.credit_amount,0)) credit_amount FROM carrier_freight_invoices i JOIN carrier_freight_invoice_lines l ON l.invoice_id=i.id LEFT JOIN shipments sh ON sh.id=l.shipment_id LEFT JOIN sales_orders o ON o.id=sh.order_id LEFT JOIN carrier_freight_disputes d ON d.invoice_line_id=l.id GROUP BY i.company_id,o.warehouse_id,date_trunc('month',i.invoice_date)::date,i.currency;
ALTER TABLE carrier_freight_invoices ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_invoices FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_invoice_lines ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_invoice_lines FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_disputes ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_disputes FORCE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_dispute_events ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_freight_dispute_events FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_carrier_freight_invoices ON carrier_freight_invoices USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_freight_invoice_lines ON carrier_freight_invoice_lines USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_freight_disputes ON carrier_freight_disputes USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);CREATE POLICY tenant_carrier_freight_dispute_events ON carrier_freight_dispute_events USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);
GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_freight_invoices,carrier_freight_invoice_lines,carrier_freight_disputes,carrier_freight_dispute_events TO stockflow_app;GRANT SELECT ON carrier_invoice_reconciliation_kpis TO stockflow_app;
CREATE INDEX carrier_freight_invoices_status_idx ON carrier_freight_invoices(company_id,status,invoice_date);CREATE INDEX carrier_freight_invoice_lines_review_idx ON carrier_freight_invoice_lines(company_id,review_status,match_status);CREATE INDEX carrier_freight_disputes_status_idx ON carrier_freight_disputes(company_id,status,owner_id);
